diff --git a/lib/src/cli/fa_tui.dart b/lib/src/cli/fa_tui.dart
index 982bf37da..f8c47012f 100644
--- a/lib/src/cli/fa_tui.dart
+++ b/lib/src/cli/fa_tui.dart
@@ -204,7 +204,7 @@ const _spinnerFrames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧',

 /// Memoized markdown+wrap pass over [FaTuiModel.outputLines]. Formatting is
 /// O(transcript) (regex-heavy markdown plus ANSI-safe wrapping) and used to
-/// run two to four times PER event (update handler, `_stickyActive`, view),
+/// run two to four times PER event (update handler, `_echoEndRow`, view),
 /// which made wheel scrolling and streaming visibly stutter. The result is
 /// shared across model copies and recomputed only when the source list
 /// (identity — every mutation path builds a new list) or the width changes,
@@ -555,26 +555,26 @@ final class FaTuiModel extends Model {
     return rows;
   }

-  /// Whether the sticky user echo is pinned right now: a run is streaming
-  /// and the echo has FULLY scrolled above the visible window. Rows are
-  /// counted wrapped (earlier lines may wrap), and the echo counts as out
-  /// only once its last row is gone — comparing the offset to the raw
-  /// [stickyIndex] line pinned a duplicate while the message was still
-  /// visible in the chat.
-  bool get _stickyActive {
-    if (!busy || stickyLines.isEmpty || stickyIndex < 0) return false;
-    // Served from the shared wrap cache (refreshed here when stale): the
-    // start row of the line just past the echo IS its end row.
+  /// Whether a turn echo is ARMED to pin: a run streams and an echo
+  /// exists. Whether it actually pins is the frame plan's call —
+  /// [_framePlanFor] dedupes the pin against the window the frame will
+  /// paint (issue #917); this getter deliberately carries no scroll math.
+  bool get _stickyArmed => busy && stickyLines.isNotEmpty && stickyIndex >= 0;
+
+  /// The first wrapped row just past the pinned echo (rows are counted
+  /// wrapped — earlier lines may wrap — and the echo counts as out of a
+  /// window iff the window top is at or past this row). Served from the
+  /// shared wrap cache, refreshed here when stale. Comparing against the
+  /// RAW [stickyIndex] line instead once pinned a duplicate while the
+  /// message was still visible in the chat.
+  int _echoEndRow() {
     _wrappedLines();
     final starts = _wrapCache.lineStartRows;
     final echoEndLine = (stickyIndex + stickyEchoLineCount).clamp(
       0,
       starts.length - 1,
     );
-    // NOTE: deliberately the RAW scroll offset — the effective (tail-riding)
-    // offset lives in view(); routing _scrollBottom through here would
-    // recurse (the plan needs sticky, sticky would need the plan's viewport).
-    return scrollOffset >= starts[echoEndLine];
+    return starts[echoEndLine];
   }

   /// The visible window of menu items (start inclusive, end exclusive).
diff --git a/lib/src/cli/fa_tui_composer.dart b/lib/src/cli/fa_tui_composer.dart
index 2038c1350..a6556b5db 100644
--- a/lib/src/cli/fa_tui_composer.dart
+++ b/lib/src/cli/fa_tui_composer.dart
@@ -68,7 +68,7 @@ extension _TuiComposerLayout on FaTuiModel {
     final scheduledWanted = scheduledCount > 0 ? 1 : 0;
     final chipsWanted = attachments.isEmpty ? 0 : attachments.length + 1;
     final queueWanted = queue.isEmpty ? 0 : queue.length + 2;
-    final stickyWanted = _stickyActive ? _formattedStickyRows(width).length : 0;
+    final stickyWanted = _stickyArmed ? _formattedStickyRows(width).length : 0;
     return (
       boardWanted,
       waitingWanted,
@@ -157,7 +157,23 @@ extension _TuiComposerLayout on FaTuiModel {
     // #502 CI failure: sticky painted but history kept its unsqueezed
     // height, the 14-row frame overran a 12-row terminal and the guard
     // dropped rows from the TOP — the echo first).
-    final sticky = stickyWanted <= consumable ? stickyWanted : 0;
+    final historyNoSticky = consumable + reserve;
+    var sticky = stickyWanted <= consumable ? stickyWanted : 0;
+    // The wrap-turn dedupe (issue #917): pin only when the echo is above
+    // the window THIS frame paints — the follow bottom, or the stored
+    // offset detached — computed with the pin's own rows taken. The old
+    // raw-[scrollOffset] check raced the painter: keystrokes re-wrap the
+    // input zone between output events, the painted window moved while
+    // the stored offset stood still, and the echo painted twice (pinned
+    // AND re-scrolled into the window) or vanished unpinned. Deciding on
+    // the painted geometry makes the dedupe exact — one paint wins under
+    // any event interleaving — and needs no recursion: both candidate
+    // heights are already in scope here.
+    if (sticky > 0) {
+      final paintedTop = _wrappedLines().length - (historyNoSticky - sticky);
+      final top = followTail ? paintedTop : scrollOffset.clamp(0, paintedTop);
+      if (top < _echoEndRow()) sticky = 0;
+    }
     consumable -= sticky;
     return _FramePlan(
       board: board,
@@ -222,7 +238,10 @@ extension _TuiComposerLayout on FaTuiModel {
   /// echo itself has scrolled out of view (Copilot-style, issue #496:
   /// paints only the plan's visible rows — yields whole when squeezed).
   int _writeStickyEcho(StringBuffer b, int visible) {
-    if (!_stickyActive || visible <= 0) return 0;
+    // The pin-vs-transcript decision is the frame plan's ([_framePlanFor]):
+    // [visible] (plan.sticky) is already zero when the transcript window
+    // owns the echo.
+    if (visible <= 0) return 0;
     final rows = _formattedStickyRows(termWidth);
     final count = visible < rows.length ? visible : rows.length;
     for (var i = 0; i < count; i++) {
diff --git a/test/cli/fa_tui_sticky_scroll_test.dart b/test/cli/fa_tui_sticky_scroll_test.dart
index c7c935a7c..360b5bd07 100644
--- a/test/cli/fa_tui_sticky_scroll_test.dart
+++ b/test/cli/fa_tui_sticky_scroll_test.dart
@@ -110,6 +110,91 @@ void main() {
         reason: 'the sticky echo must stay pinned, never scroll off');
   });
   }
+
+  // Wrap-turn dedupe (issue #917): the pin-vs-transcript decision used the
+  // RAW stored scroll offset while the frame paints at the freshly computed
+  // follow bottom. Keystrokes re-wrap the input zone between output events
+  // (the painted window moves, the stored offset does not), so a slow-PTY
+  // backspace burst landing after the last streamed line dropped the window
+  // top back below the echo while the pin stayed on: the same turn row
+  // painted twice (pinned AND in the transcript).
+  //
+  // Geometry (termHeight 24, classic chrome: 6 fixed rows → 18 history
+  // rows): prior turns + echo put the echo TEXT at window row 3 and its
+  // end past row 6 (chrome) / 5 (legacy, the dim rule merges nothing here
+  // — both counts land the text at 3). A draft of D wrapped rows shrinks
+  // history to 18-(D-1); the streamed sync then stores offset ≥ echo end
+  // while D-1 ≥ echo rows above the text, and deleting the draft drops the
+  // painted window top back ONTO the text row — pre-fix: pin still on.
+  for (final chrome in [true, false]) {
+    // A draft of 8 wrapped rows steals 7 history rows: the streamed sync
+    // (draft present) stores an offset past the echo end; deleting the
+    // draft grows the window back but the pin reclaims 2 of the rows, so
+    // the painted top lands exactly on the echo text while the stored
+    // offset still says the echo is above the window.
+    const draftRows = 8;
+    // chrome's bubble echo block is one line taller than the legacy rule
+    // echo — the same dup geometry lands one streamed line earlier.
+    final answers = chrome ? 11 : 12;
+    test('deleting a wrapped draft mid-run never duplicates the pinned '
+        'echo (chrome=$chrome, #917)', () {
+      addTearDown(() => tuiChromeEnabled = true);
+      tuiChromeEnabled = chrome;
+      var model = FaTuiModel(
+        callbacks: callbacks(),
+        isExited: () => false,
+        termWidth: 80,
+        termHeight: 24,
+        outputLines: const ['older line one', 'older line two', ''],
+      );
+
+      // Real submit path (idle), then the run bracket lands.
+      model = model.copyWith(inputText: 'the racy prompt row');
+      model = send(model, KeyPressMsg(const TeaKey(code: KeyCode.enter)));
+      model = send(model, const BusyMsg(true, source: 'run'));
+      expect(model.busy, isTrue, reason: 'submit must start a run');
+
+      // Stream the answer; the echo stays visible in the transcript.
+      for (var i = 0; i < answers; i++) {
+        model = send(model, OutputMsg('answer line $i', newline: true));
+      }
+
+      // Mid-run the owner composes a long wrapped draft: the input zone
+      // grows, the history window shrinks — keystrokes never move the
+      // stored scroll offset.
+      final draft = ('loremipsum ' * (7 * draftRows)).trim();
+      for (final ch in draft.split('')) {
+        model = send(model, KeyPressMsg(TeaKey(code: KeyCode.rune, text: ch)));
+      }
+      // One more streamed line WITH the draft present: the stored offset
+      // syncs to the bottom of the draft-squeezed window — past the echo.
+      model = send(model, OutputMsg('answer line $answers', newline: true));
+
+      List<String> rows() => model.view().content
+          .split('\n')
+          .map((l) => l.replaceAll(ansi, ''))
