  int _menuLines(int start, int end) {
    var lines = 1 + (end - start); // title + items
    lines += _groupHeadersIn(start, end); // section headers
    if (start > 0) lines++; // '↑ more'
    if (end < menuItems.length) lines++; // '↓ more'
