    test('streaming under the pinned sticky echo never scrolls the screen '
        '(chrome=$chrome)', () {
      addTearDown(() => tuiChromeEnabled = true);
      tuiChromeEnabled = chrome;
    var model = FaTuiModel(
      callbacks: callbacks(),
      isExited: () => false,
      termWidth: 80,
      termHeight: 80,
    );

