    final waiting = section(waitingWanted);
    final scheduled = section(scheduledWanted);
    final chips = section(chipsWanted);
    final queueTake = section(queueWanted);
    final (queueVisible, queueHeader, queueHint) = _queueYield(
      queueTake,
      queueWanted,
